<script setup lang="ts">
import { computed,nextTick,onBeforeUnmount,onMounted,ref,watch } from 'vue';
import type { MusicQueueMode,MusicSource,MusicTrack,PlaybackSessionSnapshot,PlayerLoadStatus,PlayerStats } from '@free-new-desk/contracts';
import MusicNetworkSourceDialog from '../components/MusicNetworkSourceDialog.vue';

import { parseLrc,activeLyricIndex,type LrcLine } from '@free-new-desk/contracts';
import { clockStats as stats,clockRuntime as runtime,clockLoadStatus as loadStatus,clockPosition,clockStale,startPlaybackClock,refreshPlaybackClock,seekPlayback } from '../stores/playback-clock.js';
import MusicArtwork from '../components/MusicArtwork.vue';
import MusicIcon from '../components/MusicIcon.vue';
const lyricsElement=ref<HTMLElement|null>(null),manualFollowUntil=ref(0),lyricOffset=ref(0),queueCollapsed=ref(false);
let seekTarget:{loadId:string;requestId:string}|undefined,polling=false;
function beginSeek(){if(!runtime.value.loadId)return;seeking.value=true;seekTarget={loadId:runtime.value.loadId,requestId:runtime.value.requestId};}
function cancelSeek(){seeking.value=false;seekTarget=undefined;}
function previewSeek(){if(!seekTarget)beginSeek();}
function manualLyrics(){manualFollowUntil.value=Date.now()+4000;}
function followLyrics(){const box=lyricsElement.value,item=box?.querySelector<HTMLElement>('.active');if(!box||!item||manualFollowUntil.value>Date.now())return;box.scrollTo({top:item.offsetTop-box.offsetTop-box.clientHeight/2+item.clientHeight/2,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function resumeFollow(){manualFollowUntil.value=0;followLyrics();}
function adjustLyrics(delta:number){lyricOffset.value+=delta;if(current.value)localStorage.setItem('music.lyricOffset.'+current.value.id,String(lyricOffset.value));}
function removeQueue(id:string){queueIds.value=queueIds.value.filter(v=>v!==id);persistQueue();}
function moveQueue(id:string,delta:number){const i=queueIds.value.indexOf(id),j=i+delta;if(i<0||j<0||j>=queueIds.value.length)return;const next=[...queueIds.value];[next[i],next[j]]=[next[j]!,next[i]!];queueIds.value=next;persistQueue();}
async function chooseCurrentArtwork(){if(current.value){const result=await window.desktop.music.chooseArtwork({trackId:current.value.id});if(result)artwork.value=result;}}

const TRACK_ROW_HEIGHT=48,VIRTUAL_OVERSCAN=8,VIRTUAL_WINDOW=48;
const sources=ref<MusicSource[]>([]);const tracks=ref<MusicTrack[]>([]);const libraryTracks=ref<MusicTrack[]>([]);const sourceId=ref('');const query=ref('');const tab=ref<'tracks'|'albums'|'artists'>('tracks');const onlyFavorites=ref(false);const loading=ref(false);const status=ref('');const current=ref<MusicTrack|null>(null);const artwork=ref('');const lyrics=ref<LrcLine[]>([]);const rawLyrics=ref('');const lyricsKind=ref<'synced'|'plain'|'instrumental'|'not-found'>('not-found');const lyricsProvider=ref('');const queueIds=ref<string[]>([]);const mode=ref<MusicQueueMode>((localStorage.getItem('music.mode') as MusicQueueMode)||'sequence');const volume=ref(Number(localStorage.getItem('music.volume')??80));const seeking=ref(false);const seekValue=ref(0);const trackScrollTop=ref(0);const trackList=ref<HTMLElement|null>(null);const networkSourceOpen=ref(false);let timer:ReturnType<typeof setInterval>|undefined;let consumedEof='';let searchTimer:ReturnType<typeof setTimeout>|undefined;let removeRuntime:(()=>void)|undefined;let assetGeneration=0;let searchGeneration=0;let playGeneration=0;let lastProgressSavedAt=0;
const sourceMap=computed(()=>new Map(sources.value.map(item=>[item.id,item])));const trackMap=computed(()=>new Map(libraryTracks.value.map(item=>[item.id,item])));const queue=computed(()=>queueIds.value.map(id=>trackMap.value.get(id)).filter((item):item is MusicTrack=>Boolean(item)));const filtered=computed(()=>onlyFavorites.value?tracks.value.filter(item=>item.favorite):tracks.value);const virtualStart=computed(()=>Math.max(0,Math.floor(trackScrollTop.value/TRACK_ROW_HEIGHT)-VIRTUAL_OVERSCAN));const visibleTracks=computed(()=>filtered.value.slice(virtualStart.value,virtualStart.value+VIRTUAL_WINDOW));const virtualTop=computed(()=>virtualStart.value*TRACK_ROW_HEIGHT);const virtualBottom=computed(()=>Math.max(0,(filtered.value.length-virtualStart.value-visibleTracks.value.length)*TRACK_ROW_HEIGHT));const artists=computed(()=>[...new Set(filtered.value.map(item=>item.artist||'未知艺人'))].sort((a,b)=>a.localeCompare(b)));const albums=computed(()=>{const groups=new Map<string,{key:string;title:string;artist:string;track:MusicTrack;count:number}>();for(const track of filtered.value){const key=JSON.stringify([track.sourceId,track.relativePath.replace(/[/\\][^/\\]+$/,''),track.album,track.artist]);const row=groups.get(key);if(row)row.count++;else groups.set(key,{key,title:track.album||'未知专辑',artist:track.artist,track,count:1});}return [...groups.values()];});const currentIndex=computed(()=>current.value?queue.value.findIndex(item=>item.id===current.value?.id):-1);const activeLyric=computed(()=>activeLyricIndex(lyrics.value,clockPosition.value+lyricOffset.value));const nowFormat=computed(()=>current.value?.cueTrack?`CUE #${String(current.value.cueTrack).padStart(2,'0')} · ${current.value.format}`:current.value?.format||'—');const nowSource=computed(()=>current.value?sourceMap.value.get(current.value.sourceId)?.name??'':'');const lyricStatus=computed(()=>lyricsKind.value==='synced'?'逐行同步'+(lyricsProvider.value?' · '+lyricsProvider.value:''):lyricsKind.value==='plain'?'普通文本'+(lyricsProvider.value?' · '+lyricsProvider.value:''):lyricsKind.value==='instrumental'?'纯音乐 / 器乐曲':'暂无歌词');
function formatTime(value:number|undefined){const total=Math.max(0,Math.floor(value??0));return `${Math.floor(total/60).toString().padStart(2,'0')}:${(total%60).toString().padStart(2,'0')}`;}

function persistQueue(){localStorage.setItem('music.queue',JSON.stringify(queueIds.value.slice(0,2000)));}
function restoreQueue(){try{const parsed=JSON.parse(localStorage.getItem('music.queue')??'[]') as unknown;if(Array.isArray(parsed))queueIds.value=parsed.filter((item):item is string=>typeof item==='string').slice(0,2000);}catch{queueIds.value=[];}}
function readProgress():Record<string,number>{try{const parsed=JSON.parse(localStorage.getItem('music.progress')??'{}') as unknown;if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed))return parsed as Record<string,number>;}catch{/* ignore damaged local state */}return{};}
function saveProgress(trackId:string,position:number,duration?:number){const all=readProgress();if(!Number.isFinite(position)||position<3||(duration&&duration-position<10))delete all[trackId];else all[trackId]=Math.round(position*10)/10;const bounded=Object.fromEntries(Object.entries(all).slice(-500));localStorage.setItem('music.progress',JSON.stringify(bounded));}
function resetTrackScroll(){trackScrollTop.value=0;if(trackList.value)trackList.value.scrollTop=0;}
function onTrackScroll(event:Event){trackScrollTop.value=(event.currentTarget as HTMLElement).scrollTop;}
async function loadSources(){sources.value=await window.desktop.music.listSources();if(sourceId.value&&!sources.value.some(item=>item.id===sourceId.value))sourceId.value='';}
async function loadTracks(){const generation=++searchGeneration;loading.value=true;try{const result=await window.desktop.music.listTracks(sourceId.value||undefined,query.value.trim()||undefined,50_000);if(generation!==searchGeneration)return;tracks.value=result;resetTrackScroll();}catch(error){status.value=error instanceof Error?error.message:String(error);}finally{loading.value=false;}}
async function refreshLibrary(){await loadSources();libraryTracks.value=await window.desktop.music.listTracks(undefined,undefined,50_000);await loadTracks();}
async function addLocalSource(){loading.value=true;try{const result=await window.desktop.music.addLocalSource();if(!result.canceled){status.value=`已扫描 ${result.count??0} 首音乐${result.truncated?'（达到安全上限）':''}`;await refreshLibrary();if(result.source)sourceId.value=result.source.id;}}catch(error){status.value=error instanceof Error?error.message:String(error);}finally{loading.value=false;}}
async function onNetworkSourceSaved(source:MusicSource,count:number){networkSourceOpen.value=false;status.value=`已添加「${source.name}」，扫描到 ${count} 首音乐`;sourceId.value=source.id;onlyFavorites.value=false;await refreshLibrary();sourceId.value=source.id;await loadTracks();}
async function rescan(source:MusicSource){loading.value=true;source.scanState='scanning';try{const result=await window.desktop.music.scan(source.id);status.value=result.canceled?`${source.name}：扫描已取消，保留上次完整结果`:`${source.name}：扫描完成 ${result.count} 首`;await refreshLibrary();}catch(error){status.value=error instanceof Error?error.message:String(error);await loadSources();}finally{loading.value=false;}}
async function cancelScan(source:MusicSource){if(await window.desktop.music.cancelScan(source.id))status.value=`正在取消 ${source.name} 的扫描…`;}
async function removeSource(source:MusicSource){if(!window.confirm(`删除音乐来源「${source.name}」？不会删除磁盘或服务器上的音乐文件。`))return;await window.desktop.music.removeSource(source.id);if(sourceId.value===source.id)sourceId.value='';await refreshLibrary();}
function scheduleSearch(){if(searchTimer)clearTimeout(searchTimer);searchTimer=setTimeout(()=>{void loadTracks();},250);}
async function loadNowPlayingAssets(track:MusicTrack){const generation=++assetGeneration;lyricOffset.value=Number(localStorage.getItem('music.lyricOffset.'+track.id)??0);artwork.value='';rawLyrics.value='';lyrics.value=[];lyricsKind.value='not-found';lyricsProvider.value='';const applies=()=>generation===assetGeneration&&current.value?.id===track.id;await Promise.all([window.desktop.music.artwork(track.id).then(cover=>{if(applies())artwork.value=cover??'';}).catch(()=>undefined),window.desktop.music.lyricsInfo(track.id).then(info=>{if(applies()){rawLyrics.value=info.text;lyrics.value=info.kind==='synced'?parseLrc(info.text):[];lyricsKind.value=info.kind;lyricsProvider.value=info.provider??'';}}).catch(()=>undefined)]);}
async function playTrack(track:MusicTrack,initiator:'user'|'auto-next'|'restore'='user'){const generation=++playGeneration;cancelSeek();assetGeneration++;artwork.value='';rawLyrics.value='';lyrics.value=[];lyricsKind.value='not-found';lyricsProvider.value='';try{if(!queueIds.value.includes(track.id)){queueIds.value.push(track.id);queueIds.value=queueIds.value.slice(-2000);persistQueue();}status.value=`正在播放：${track.title}`;const result=await window.desktop.music.play({trackId:track.id,initiator});if(generation!==playGeneration)return;if(!result.ok)throw new Error(result.detail??'音乐加载失败');current.value=result.track;runtime.value=result.session;consumedEof='';if(initiator==='restore'){const position=readProgress()[track.id];if(typeof position==='number'&&Number.isFinite(position)&&position>2&&(!track.duration||position<track.duration-10))await seekPlayback(position,result.session.loadId!,result.session.requestId);}void loadNowPlayingAssets(result.track);await nextTick();await poll();}catch(error){const message=error instanceof Error?error.message:String(error);if(generation===playGeneration&&!message.includes('PLAYBACK_SUPERSEDED'))status.value=message;}}
function queueAll(){const selected=filtered.value.slice(0,2000);queueIds.value=selected.map(item=>item.id);persistQueue();status.value=filtered.value.length>2000?`已加入前 2000 首到播放队列（当前筛选共 ${filtered.value.length} 首）`:`已加入 ${queueIds.value.length} 首到播放队列`;}
function clearQueue(){queueIds.value=[];persistQueue();status.value='播放队列已清空';}
async function toggleFavorite(track:MusicTrack){track.favorite=await window.desktop.music.toggleFavorite(track.id);}
function nextQueueIndex(direction:1|-1):number{const items=queue.value;if(!items.length)return-1;if(mode.value==='repeat-one'&&currentIndex.value>=0)return currentIndex.value;if(mode.value==='shuffle'){if(items.length===1)return 0;let next=Math.floor(Math.random()*items.length);if(next===currentIndex.value)next=(next+1)%items.length;return next;}const base=currentIndex.value>=0?currentIndex.value:direction>0?-1:0;return(base+direction+items.length)%items.length;}
async function playAdjacent(direction:1|-1,initiator:'user'|'auto-next'='user'){const index=nextQueueIndex(direction),track=queue.value[index];if(track)await playTrack(track,initiator);}
function setMode(next:MusicQueueMode){mode.value=next;localStorage.setItem('music.mode',next);}
function cycleMode(){setMode(mode.value==='sequence'?'repeat-one':mode.value==='repeat-one'?'shuffle':'sequence');}
function modeLabel(){return mode.value==='sequence'?'顺序播放':mode.value==='repeat-one'?'单曲循环':'随机播放';}
async function togglePause(){if(runtime.value.domain!=='music'){if(current.value)await playTrack(current.value,'restore');return;}await window.desktop.playback.control({command:'pause',value:!(stats.value?.paused??false)});await poll();}
async function toggleMute(){await window.desktop.playback.control({command:'mute',value:!(stats.value?.muted??false)});await poll();}
async function persistVolume(){const safe=Math.max(0,Math.min(100,Math.round(volume.value)));volume.value=safe;localStorage.setItem('music.volume',String(safe));await window.desktop.playback.control({command:'volume',value:safe});}
async function seek(){const target=seekTarget;if(!target)return;seekTarget=undefined;seeking.value=false;try{await seekPlayback(seekValue.value,target.loadId,target.requestId);}catch(error){status.value=error instanceof Error?error.message:String(error);}}

async function onNaturalEnd(){if(current.value)saveProgress(current.value.id,0);if(mode.value==='repeat-one'&&current.value)await playTrack(current.value,'auto-next');else await playAdjacent(1,'auto-next');}
async function poll(){if(polling)return;polling=true;try{await refreshPlaybackClock();const s=stats.value,l=loadStatus.value,r=runtime.value;if(r.domain!=='music')return;
if(r.trackId&&r.trackId!==current.value?.id){const track=trackMap.value.get(r.trackId);if(track){current.value=track;void loadNowPlayingAssets(track);}}
if(s&&!clockStale.value&&current.value&&Date.now()-lastProgressSavedAt>=5000){saveProgress(current.value.id,s.position,s.duration);lastProgressSavedAt=Date.now();}
const id=r.loadId??'';if(id&&r.requestId&&l?.loadId===id&&l.status==='ended'&&l.error==='eof'&&consumedEof!==id){consumedEof=id;const claimed=await window.desktop.playback.claimNaturalEnd({loadId:id,requestId:r.requestId,domain:'music'});if(claimed)void onNaturalEnd();}
}finally{polling=false;}}

function selectArtist(artist:string){query.value=artist;tab.value='tracks';scheduleSearch();}
function selectAlbum(album:string){query.value=album;tab.value='tracks';scheduleSearch();}
function keydown(event:KeyboardEvent){const target=event.target as HTMLElement|null;if(target&&['INPUT','SELECT','TEXTAREA'].includes(target.tagName))return;if(event.code==='Space'&&runtime.value.domain==='music'){event.preventDefault();void togglePause();return;}if((event.key==='ArrowLeft'||event.key==='ArrowRight')&&runtime.value.domain==='music'&&runtime.value.loadId){event.preventDefault();const next=Math.max(0,clockPosition.value+(event.key==='ArrowLeft'?-10:10));void seekPlayback(next,runtime.value.loadId,runtime.value.requestId).catch(error=>{status.value=error instanceof Error?error.message:String(error);});}}
onMounted(async()=>{startPlaybackClock();restoreQueue();removeRuntime=window.desktop.playback.onRuntimeSessionChanged(value=>{runtime.value=value;if(value.domain!=='music'&&value.status==='playing')status.value=`当前播放器已切换到${value.domain==='live'?'直播':'点播'}模式`;});window.addEventListener('keydown',keydown);await refreshLibrary();const savedCurrent=localStorage.getItem('music.currentTrack');if(savedCurrent){const track=libraryTracks.value.find(item=>item.id===savedCurrent);if(track)current.value=track;}if(current.value)void loadNowPlayingAssets(current.value);timer=setInterval(()=>{void poll();},275);void poll();});
onBeforeUnmount(()=>{assetGeneration+=1;playGeneration+=1;searchGeneration+=1;if(timer)clearInterval(timer);if(searchTimer)clearTimeout(searchTimer);removeRuntime?.();window.removeEventListener('keydown',keydown);if(current.value){localStorage.setItem('music.currentTrack',current.value.id);if(runtime.value.domain==='music'&&stats.value)saveProgress(current.value.id,stats.value.position,stats.value.duration);}});
watch(clockPosition,value=>{if(!seeking.value)seekValue.value=value;});
watch(activeLyric,()=>{void nextTick(followLyrics);});
watch(()=>runtime.value.loadId,()=>{cancelSeek();assetGeneration++;artwork.value='';lyrics.value=[];rawLyrics.value='';lyricsKind.value='not-found';lyricsProvider.value='';const track=runtime.value.trackId?trackMap.value.get(runtime.value.trackId):undefined;if(track){current.value=track;void loadNowPlayingAssets(track);}});
</script>

<template>
  <section class="music-page">
    <header class="music-heading"><div><h1>音乐</h1><p>私人音乐库 <span class="concept-tag">V1.4.13</span></p></div><div class="music-actions"><label class="music-search"><span>⌕</span><input v-model="query" data-search-input placeholder="搜索曲目、艺人或专辑" @input="scheduleSearch"/></label><button class="soft-button" @click="addLocalSource">添加本地音乐</button><button class="accent-button" @click="networkSourceOpen=true">添加网络来源</button></div></header>
    <div class="music-layout">
      <aside class="music-library panel-like"><h3>音乐库</h3><button :class="{active:!sourceId&&!onlyFavorites}" @click="sourceId='';onlyFavorites=false;loadTracks()"><span>▧</span>全部曲目<b>{{tracks.length}}</b></button><button @click="tab='artists';onlyFavorites=false"><span>♙</span>艺人<b>{{artists.length}}</b></button><button @click="tab='albums';onlyFavorites=false"><span>◉</span>专辑<b>{{albums.length}}</b></button><button :class="{active:onlyFavorites}" @click="onlyFavorites=true;tab='tracks';resetTrackScroll()"><span>☆</span>我的收藏<b>{{tracks.filter(t=>t.favorite).length}}</b></button><div class="source-title"><h3>来源</h3><button title="添加本地来源" @click="addLocalSource">＋</button></div><div v-if="sources.length" class="source-list"><div v-for="source in sources" :key="source.id" class="source-row" :class="{selected:sourceId===source.id}" @click="sourceId=source.id;onlyFavorites=false;loadTracks()"><span class="source-dot" :class="source.scanState"/><div><strong>{{source.name}}</strong><small>{{source.kind==='local'?'本地音乐':source.kind==='webdav'?'WebDAV':'SMB'}} · {{source.scanState==='error'?'不可用':source.scanState==='scanning'?'扫描中':'已就绪'}}</small></div><span class="source-tools"><button v-if="source.scanState==='scanning'" title="取消扫描" @click.stop="cancelScan(source)">■</button><button v-else title="重新扫描" @click.stop="rescan(source)">↻</button><button title="删除来源" @click.stop="removeSource(source)">×</button></span></div></div><div v-else class="empty-source">还没有音乐来源</div><div class="scan-footer"><span>✓ {{loading?'正在扫描或加载':'音乐库已就绪'}}</span><button @click="refreshLibrary">↻ 刷新音乐库</button></div></aside>
      <main class="music-center panel-like" :class="{collapsed:queueCollapsed}"><div class="music-tabs"><button :class="{active:tab==='tracks'}" @click="tab='tracks'">曲目</button><button :class="{active:tab==='albums'}" @click="tab='albums'">专辑</button><button :class="{active:tab==='artists'}" @click="tab='artists'">艺人</button><span/><button class="text-action" @click="queueAll">全部加入队列</button></div>
        <div v-if="tab==='tracks'" class="track-section"><div class="table-title"><strong>{{onlyFavorites?'我的收藏':'全部曲目'}}</strong><span>{{filtered.length}} 首</span></div><div class="track-head"><span></span><span>封面</span><span>标题</span><span>艺人</span><span>专辑</span><span>格式</span><span>时长</span><span></span></div><div ref="trackList" class="track-list" @scroll="onTrackScroll"><div class="virtual-spacer" :style="{height:`${virtualTop}px`}"/><div v-for="track in visibleTracks" :key="track.id" class="track-row" :class="{playing:current?.id===track.id&&runtime.domain==='music'}" role="button" tabindex="0" @dblclick="playTrack(track)" @keydown.enter="playTrack(track)"><span class="playing-bars">{{current?.id===track.id&&runtime.domain==='music'?'▮▮':'▶'}}</span><span class="track-thumbnail"><MusicArtwork :track-id="track.id"/></span><span class="track-title"><strong>{{track.title}}</strong><small>{{track.cueTrack?`CUE #${String(track.cueTrack).padStart(2,'0')} · `:''}}{{track.relativePath}}</small></span><span>{{track.artist||'未知艺人'}}</span><span>{{track.album||'未知专辑'}}</span><span><em>{{track.cueTrack?'CUE':track.format}}</em></span><span>{{formatTime(track.duration)}}</span><span class="row-buttons"><button :aria-label="track.favorite?'取消收藏':'收藏'" @click.stop="toggleFavorite(track)">{{track.favorite?'★':'☆'}}</button><button aria-label="播放" @click.stop="playTrack(track)">▶</button></span></div><div class="virtual-spacer" :style="{height:`${virtualBottom}px`}"/><div v-if="!filtered.length" class="music-empty">{{sources.length?'没有匹配曲目':'点击“添加本地音乐”或“添加网络来源”建立音乐库。'}}</div></div></div>
        <div v-else-if="tab==='albums'" class="entity-grid"><button v-for="album in albums" :key="album.key" @click="selectAlbum(album.title)"><span class="entity-art"><MusicArtwork :track-id="album.track.id"/></span><strong>{{album.title}}</strong><small>{{album.artist}} · {{album.count}} 首</small></button></div>
        <div v-else class="entity-grid"><button v-for="artist in artists" :key="artist" @click="selectArtist(artist)"><span class="entity-art artist-art"><MusicArtwork :artist="artist"/></span><strong>{{artist}}</strong><small>{{filtered.filter(t=>(t.artist||'未知艺人')===artist).length}} 首</small></button></div>
        <section class="queue-box"><div class="queue-heading"><button @click="queueCollapsed=!queueCollapsed">{{queueCollapsed?'展开':'收起'}}播放队列 · {{queue.length}} 首</button><span/><button @click="cycleMode">{{modeLabel()}}</button><button @click="clearQueue">清空</button></div><div v-show="!queueCollapsed" class="queue-items"><div v-for="(track,index) in queue" :key="track.id" class="queue-row" :class="{current:track.id===current?.id}"><button @click="playTrack(track)">{{index+1}} · {{track.title}} — {{track.artist}}</button><button aria-label="上移" @click="moveQueue(track.id,-1)">↑</button><button aria-label="下移" @click="moveQueue(track.id,1)">↓</button><button aria-label="移出队列" @click="removeQueue(track.id)">×</button></div><div v-if="!queue.length" class="queue-empty">双击曲目或点击播放，将音乐加入队列。</div></div></section>
      </main>
      <aside class="now-playing panel-like"><h3>正在播放</h3><div class="cover-frame" @contextmenu.prevent="chooseCurrentArtwork"><img v-if="artwork" :src="artwork" :alt="current?.title??'封面'"/><div v-else class="cover-placeholder">♫</div></div><h2>{{current?.title??'尚未播放'}}</h2><p>{{current?.artist||'选择一首曲目开始播放'}}<span v-if="current?.album"> · {{current.album}}</span></p><div class="quality"><span>{{nowFormat}}</span><span v-if="stats?.sampleRate">{{Math.round(stats.sampleRate/1000)}} kHz</span><span v-if="stats?.audioChannels">{{stats.audioChannels}} ch</span><small>{{nowSource}}</small></div><div class="lyrics-title"><strong>歌词</strong><span>{{lyricStatus}}</span></div><div ref="lyricsElement" class="lyrics" :class="{empty:!rawLyrics}" @wheel.passive="manualLyrics" @pointerdown="manualLyrics"><template v-if="lyrics.length"><p v-for="(line,index) in lyrics" :key="`${line.time}-${index}`" :class="{active:index===activeLyric}">{{line.text||'♪'}}</p></template><p v-else>{{rawLyrics||(lyricsKind==='instrumental'?'该录音标记为纯音乐 / 器乐曲':current?'未找到本地或在线歌词':'播放音乐后显示歌词')}}</p></div><div class="lyric-tools"><button @click="adjustLyrics(-.25)">−0.25s</button><button @click="resumeFollow">回到当前歌词</button><button @click="adjustLyrics(.25)">+0.25s</button></div></aside>
    </div>
